INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','2','ar','Roblox Gift Card — Robux code — فوري','Roblox Gift Card أصلي — Robux code. سيتم تسليم الرمز الخاص بك تلقائيًا مباشرة بعد الدفع.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: اتبع التعليمات المرسلة مع طلبك. تواصل مع البائع من صفحة طلبك إذا حدث أي خطأ.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','2','es','Roblox Gift Card — código Robux — Instantáneo','Tarjeta de regalo Roblox auténtica — código Robux. Tu código se entrega automáticamente justo después del pago.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: sigue las instrucciones enviadas con tu pedido. Contacta al vendedor desde la página de tu pedido si algo sale mal.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','2','fr','Roblox Gift Card — code Robux — Instantané','Carte-cadeau Roblox authentique — code Robux. Votre code est livré automatiquement juste après le paiement.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: suivez les instructions envoyées avec votre commande. Contactez le vendeur depuis la page de votre commande si quelque chose ne va pas.','2026-10-16 05:23:06');
